assert_eq!(array.capacity(), 16);
```

Returns the remaining spare capacity of the vector as a slice of
`MaybeUninit<T>`.

The returned slice can be used to fill the vector with data (e.g. by
reading from a file) before marking the data as initialized using the
[`set_len`] method.

[`set_len`]: ArrayVec::set_len

# Examples

```
use arrayvec::ArrayVec;

// Allocate vector big enough for 10 elements.
let mut v: ArrayVec<i32, 10> = ArrayVec::new();

// Fill in the first 3 elements.
let uninit = v.spare_capacity_mut();
uninit[0].write(0);
uninit[1].write(1);
uninit[2].write(2);

// Mark the first 3 elements of the vector as being initialized.
unsafe {
    v.set_len(3);
}

assert_eq!(&v[..], &[0, 1, 2]);
```

Create a new empty `ArrayString` (const fn).

Capacity is inferred from the type parameter.

```
use arrayvec::ArrayString;

static ARRAY: ArrayString<1024> = ArrayString::new_const();
```

Create a new empty `ArrayString`.

Capacity is inferred from the type parameter.

```
use arrayvec::ArrayString;

let mut string = ArrayString::<16>::new();
string.push_str("foo");
assert_eq!(&string[..], "foo");
assert_eq!(string.capacity(), 16);
```

Retains only the elements specified by the predicate.

In other words, remove all elements `e` such that `f(&mut e)` returns false.
This method operates in place and preserves the order of the retained
elements.

```
use arrayvec::ArrayVec;

let mut array = ArrayVec::from([1, 2, 3, 4]);
array.retain(|x| *x & 1 != 0 );
assert_eq!(&array[..], &[1, 3]);
