};
```

Building lazily:

```
use base64::alphabet::Alphabet;
use std::sync::LazyLock;

static CUSTOM: LazyLock<Alphabet> = LazyLock::new(||
    Alphabet::new("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/").unwrap()
);
```

