use std::io::Write;

# fn main() -> std::io::Result<()> {
let file = File::open("LICENSE-APACHE")?;
let mut mmap = unsafe { MmapOptions::new().map_copy(&file)? };
(&mut mmap[..]).write_all(b"Hello, world!")?;
# Ok(())
# }
```

