```
use rand::{Rng, TryRngCore};
use rayon::prelude::*;

let mut v = vec![0u8; 1_000_000];

v.par_chunks_mut(1000)
    .try_for_each_init(
        || rand::rng(),
        |rng, chunk| rng.try_fill_bytes(chunk),
