```rust
use tinyvec::*;
let mut tv = tiny_vec!([i32; 2] => 1, 2, 3);
assert!(tv.is_heap());
let _ = tv.pop();
assert!(tv.is_heap());
tv.shrink_to_fit();
assert!(tv.is_inline());
```

