```rust
use tinyvec::*;
let mut av = array_vec!([&'static str; 4] => "one", "two", "three");
av.insert(1, "four");
assert_eq!(av.as_slice(), &["one", "four", "two", "three"]);
assert_eq!(av.try_insert(4, "five"), Some("five"));
