```rust
# use winnow::prelude::*;
# use winnow::{error::ErrMode, error::ContextError};
# use winnow::token::one_of;
assert_eq!(one_of::<_, _, ContextError>(['a', 'b', 'c']).parse_peek("b"), Ok(("", 'b')));
