struct MyStruct<T>(T);
writeable::impl_writeable_delegate!(MyStruct<T>, |&self| &self.0, where T: Writeable);
writeable::impl_display_with_writeable!(MyStruct<T>, where T: Writeable);

writeable::assert_writeable_eq!(
