// Invalid interface names
InterfaceName::try_from("").unwrap_err();
InterfaceName::try_from(":start.with.a.colon").unwrap_err();
InterfaceName::try_from("double..dots").unwrap_err();
InterfaceName::try_from(".").unwrap_err();
