# use serde_derive::Deserialize;
use chrono::serde::ts_microseconds_option::deserialize as from_micro_tsopt;
#[derive(Debug, PartialEq, Deserialize)]
struct S {
    #[serde(deserialize_with = "from_micro_tsopt")]
    time: Option<DateTime<Utc>>,
