// Unconditional niceness.
assert_eq!(
    NiceFloat::from(NiceFloat::div_u128(3, 100)).as_str(),
    "0.03000000", // Result was good.
);
assert_eq!(
    NiceFloat::from(NiceFloat::div_u128(3, 0)).as_str(),
    "∞", // Result was infinite!
);
```

