table.insert_unique(hasher(&3), (3, 'c'), |val| hasher(&val.0));

let index = table.find_bucket_index(hasher(&2), |val| val.0 == 2).unwrap();
assert!(std::ptr::eq(
    table.get_bucket_mut(index).unwrap(),
    unsafe { table.get_bucket_unchecked_mut(index) },
));
# }
