table.insert_unique(hasher(&"a"), "a", hasher);
table.insert_unique(hasher(&"b"), "b", hasher);

// Will print in an arbitrary order.
for index in table.iter_buckets() {
    println!("{index}: {}", table.get_bucket(index).unwrap());
}
# }
