Return something that can be downcast'ed (typically self).

Use this to retrieve the concrete model from a [`ModelRc`] stored
in your tree of UI elements.

```
# use i_slint_core::model::*;
# use std::rc::Rc;
let handle = ModelRc::new(VecModel::from(vec![1i32, 2, 3]));
// later:
handle.as_any().downcast_ref::<VecModel<i32>>().unwrap().push(4);
assert_eq!(handle.row_data(3).unwrap(), 4);
```

Note: Custom models must implement this method for the cast to succeed.
A valid implementation is to return `self`:
```ignore
    fn as_any(&self) -> &dyn core::any::Any { self }
```

## Troubleshooting
A common reason why the downcast fails at run-time is because of a type-mismatch
between the model created and the model downcasted. To debug this at compile time,
try matching the model type used for the downcast explicitly at model creation time.
In the following example, the downcast fails at run-time:

```
# use i_slint_core::model::*;
# use std::rc::Rc;
let model = VecModel::from_slice(&[3i32, 2, 1])
    .filter(Box::new(|v: &i32| *v >= 2) as Box<dyn Fn(&i32) -> bool>);
let model_rc = ModelRc::new(model);
assert!(model_rc.as_any()
    .downcast_ref::<FilterModel<VecModel<i32>, Box<dyn Fn(&i32) -> bool>>>()
    .is_none());
```

To debug this, let's make the type explicit. It fails to compile.

```compile_fail
# use i_slint_core::model::*;
# use std::rc::Rc;
let model: FilterModel<VecModel<i32>, Box<dyn Fn(&i32) -> bool>>
    = VecModel::from_slice(&[3i32, 2, 1])
      .filter(Box::new(|v: &i32| *v >= 2) as Box<dyn Fn(&i32) -> bool>);
let model_rc = ModelRc::new(model);
assert!(model_rc.as_any()
    .downcast_ref::<FilterModel<VecModel<i32>, Box<dyn Fn(&i32) -> bool>>>()
    .is_none());
```

The compiler tells us that the type of model is not `FilterModel<VecModel<..>>`,
but instead `from_slice()` already returns a `ModelRc`, so the correct type to
use for the downcast is wrapped in `ModelRc`:

```
# use i_slint_core::model::*;
# use std::rc::Rc;
let model: FilterModel<ModelRc<i32>, Box<dyn Fn(&i32) -> bool>>
    = VecModel::from_slice(&[3i32, 2, 1])
      .filter(Box::new(|v: &i32| *v >= 2) as Box<dyn Fn(&i32) -> bool>);
let model_rc = ModelRc::new(model);
assert!(model_rc.as_any()
    .downcast_ref::<FilterModel<ModelRc<i32>, Box<dyn Fn(&i32) -> bool>>>()
    .is_some());
```

Same as get() but without registering a dependency

This allow to optimize bindings that know that they might not need to
re_evaluate themselves when the property change or that have registered
the dependency in another way.

## Example
```
use std::rc::Rc;
use i_slint_core::Property;
let prop1 = Rc::pin(Property::new(100));
let prop2 = Rc::pin(Property::<i32>::default());
prop2.as_ref().set_binding({
    let prop1 = prop1.clone(); // in order to move it into the closure.
    move || { prop1.as_ref().get_untracked() + 30 }
});
assert_eq!(prop2.as_ref().get(), 130);
prop1.set(200);
// changing prop1 do not affect the prop2 binding because no dependency was registered
assert_eq!(prop2.as_ref().get(), 130);
```

Provides rows that are generated by a map function based on the rows of another Model

When the other Model is updated, the `MapModel` is updated accordingly.

Generic parameters:
* `M` the type of the wrapped `Model`.
* `F` the map function.

## Example

Here we have a [`VecModel`] holding rows of a custom type `Name`.
It is then mapped into a `MapModel` of [`SharedString`]s

```
# use slint::{Model, VecModel, SharedString, MapModel};
#[derive(Clone)]
struct Name {
    first: String,
    last: String,
}

let model = VecModel::from(vec![
    Name { first: "Hans".to_string(), last: "Emil".to_string() },
    Name { first: "Max".to_string(), last: "Mustermann".to_string() },
    Name { first: "Roman".to_string(), last: "Tisch".to_string() },
]);

let mapped_model = MapModel::new(model, |n|
    slint::format!("{}, {}", n.last, n.first)
);

assert_eq!(mapped_model.row_data(0).unwrap(), SharedString::from("Emil, Hans"));
assert_eq!(mapped_model.row_data(1).unwrap(), SharedString::from("Mustermann, Max"));
assert_eq!(mapped_model.row_data(2).unwrap(), SharedString::from("Tisch, Roman"));

```

Alternatively you can use the shortcut [`ModelExt::map`].
```
# use slint::{Model, ModelExt, VecModel, SharedString, MapModel};
# #[derive(Clone)]
# struct Name {
#     first: String,
#     last: String,
# }
let mapped_model = VecModel::from(vec![
    Name { first: "Hans".to_string(), last: "Emil".to_string() },
    Name { first: "Max".to_string(), last: "Mustermann".to_string() },
    Name { first: "Roman".to_string(), last: "Tisch".to_string() },
])
.map(|n| slint::format!("{}, {}", n.last, n.first));
# assert_eq!(mapped_model.row_data(0).unwrap(), SharedString::from("Emil, Hans"));
# assert_eq!(mapped_model.row_data(1).unwrap(), SharedString::from("Mustermann, Max"));
# assert_eq!(mapped_model.row_data(2).unwrap(), SharedString::from("Tisch, Roman"));
```

If you want to modify the underlying [`VecModel`] you can give it a [`Rc`] of the MapModel:
```
# use std::rc::Rc;
# use slint::{Model, VecModel, SharedString, MapModel};
# #[derive(Clone)]
# struct Name {
#     first: String,
#     last: String,
# }
let model = Rc::new(VecModel::from(vec![
    Name { first: "Hans".to_string(), last: "Emil".to_string() },
    Name { first: "Max".to_string(), last: "Mustermann".to_string() },
    Name { first: "Roman".to_string(), last: "Tisch".to_string() },
]));

let mapped_model = MapModel::new(model.clone(), |n|
    slint::format!("{}, {}", n.last, n.first)
);

model.set_row_data(1, Name { first: "Minnie".to_string(), last: "Musterfrau".to_string() });

assert_eq!(mapped_model.row_data(0).unwrap(), SharedString::from("Emil, Hans"));
assert_eq!(mapped_model.row_data(1).unwrap(), SharedString::from("Musterfrau, Minnie"));
assert_eq!(mapped_model.row_data(2).unwrap(), SharedString::from("Tisch, Roman"));

```

Set a binding to this property.

Bindings are evaluated lazily from calling get, and the return value of the binding
is the new value.

If other properties have bindings depending of this property, these properties will
be marked as dirty.

Closures of type `Fn()->T` implements `Binding<T>` and can be used as a binding

## Example
```
use std::rc::Rc;
use i_slint_core::Property;
let prop1 = Rc::pin(Property::new(100));
let prop2 = Rc::pin(Property::<i32>::default());
prop2.as_ref().set_binding({
    let prop1 = prop1.clone(); // in order to move it into the closure.
    move || { prop1.as_ref().get() + 30 }
});
assert_eq!(prop2.as_ref().get(), 130);
prop1.set(200);
// A change in prop1 forced the binding on prop2 to re_evaluate
assert_eq!(prop2.as_ref().get(), 230);
```

Returns a new color that is a mix of this color and `other`. The specified factor is
clamped to be between `0.0` and `1.0` and then applied to this color, while `1.0 - factor`
is applied to `other`.

# Examples
Mix red with black half-and-half:
```
# use i_slint_core::graphics::Color;
let red = Color::from_rgb_f32(1.0, 0.0, 0.0);
let black = Color::from_rgb_f32(0.0, 0.0, 0.0);
assert_eq!(red.mix(&black, 0.5), Color::from_rgb_f32(0.5, 0.0, 0.0));
```

Mix Purple with OrangeRed,  with `75%` purple and `25%` orange red ratio:
```
# use i_slint_core::graphics::{Color, RgbaColor};
let purple = Color::from_rgb_u8(128, 0, 128);
let orange_red = Color::from_rgb_u8(255, 69, 0);
assert_eq!(purple.mix(&orange_red, 0.75), Color::from_rgb_f32(0.6264706, 0.06764706, 0.37647063));
```

The `Key` enum is used to map a specific key by name e.g. `Key::Control` to an
internal used unicode representation. The enum is convertible to [`std::char`] and [`slint::SharedString`](`crate::SharedString`).
Use this with [`slint::platform::WindowEvent`](`crate::platform::WindowEvent`) to supply key events to Slint's platform abstraction.

# Example

Send an tab key press event to a window

```
use slint::platform::{WindowEvent, Key};
fn send_tab_pressed(window: &slint::Window) {
    window.dispatch_event(WindowEvent::KeyPressed { text: Key::Tab.into() });
}
```

ModelRc is a type wrapper for a reference counted implementation of the [`Model`] trait.

Models are used to represent sequences of the same data type. In `.slint` code those
are represented using the `[T]` array syntax and typically used in `for` expressions,
array properties, and array struct fields.

For example, a `property <[string]> foo` will be of type `ModelRc<SharedString>`
and, behind the scenes, wraps a `Rc<dyn Model<Data = SharedString>>.`

An array struct field will also be of type `ModelRc`:

```slint,no-preview
export struct AddressBook {
    names: [string]
}
```

When accessing `AddressBook` from Rust, the `names` field will be of type `ModelRc<SharedString>`.

There are several ways of constructing a ModelRc in Rust:

* An empty ModelRc can be constructed with [`ModelRc::default()`].
* A `ModelRc` can be constructed from a slice or an array using the [`From`] trait.
  This allocates a [`VecModel`].
* Use [`ModelRc::new()`] to construct a `ModelRc` from a type that implements the
  [`Model`] trait, such as [`VecModel`] or your own implementation.
* If you have your model already in an `Rc`, then you can use the [`From`] trait
  to convert from `Rc<dyn Model<Data = T>>` to `ModelRc`.

## Example

```rust
# i_slint_backend_testing::init_no_event_loop();
use slint::{slint, SharedString, ModelRc, Model, VecModel};
use std::rc::Rc;
slint!{
    import { Button } from "std-widgets.slint";
    export component Example {
        callback add_item <=> btn.clicked;
        in property <[string]> the_model;
        HorizontalLayout {
            for it in the_model : Text { text: it; }
            btn := Button { text: "Add"; }
        }
    }
}
let ui = Example::new().unwrap();
// Create a VecModel and put it in an Rc.
let the_model : Rc<VecModel<SharedString>> =
        Rc::new(VecModel::from(vec!["Hello".into(), "World".into()]));
// Convert it to a ModelRc.
let the_model_rc = ModelRc::from(the_model.clone());
// Pass the model to the ui: The generated set_the_model setter from the
// the_model property takes a ModelRc.
ui.set_the_model(the_model_rc);

// We have kept a strong reference to the_model, to modify it in a callback.
ui.on_add_item(move || {
    // Use VecModel API: VecModel uses the Model notification mechanism to let Slint
    // know it needs to refresh the UI.
    the_model.push("SomeValue".into());
});

// Alternative: we can re-use a getter.
let ui_weak = ui.as_weak();
ui.on_add_item(move || {
    let ui = ui_weak.unwrap();
    let the_model_rc = ui.get_the_model();
    let the_model = the_model_rc.as_any().downcast_ref::<VecModel<SharedString>>()
        .expect("We know we set a VecModel earlier");
    the_model.push("An Item".into());
});
```

### Updating the Model from a Thread

`ModelRc` is not `Send` and can only be used in the main thread.
If you want to update the model based on data coming from another thread, you need to send back the data to the main thread
using [`invoke_from_event_loop`](crate::api::invoke_from_event_loop) or
[`Weak::upgrade_in_event_loop`](crate::api::Weak::upgrade_in_event_loop).

```rust
# i_slint_backend_testing::init_integration_test_with_mock_time();
use slint::Model;
slint::slint!{
    export component TestCase inherits Window {
        in property <[string]> the_model;
        //...
    }
}
let ui = TestCase::new().unwrap();
// set a model (a VecModel)
let model = std::rc::Rc::new(slint::VecModel::<slint::SharedString>::default());
ui.set_the_model(model.clone().into());

// do some work in a thread
let ui_weak = ui.as_weak();
let thread = std::thread::spawn(move || {
    // do some work
    let new_strings = vec!["foo".into(), "bar".into()];
    // send the data back to the main thread
    ui_weak.upgrade_in_event_loop(move |ui| {
        let model = ui.get_the_model();
        let model = model.as_any().downcast_ref::<slint::VecModel<slint::SharedString>>()
            .expect("We know we set a VecModel earlier");
        model.set_vec(new_strings);
#       slint::quit_event_loop().unwrap();
    });
});
ui.run().unwrap();
```

Factory to create [`slint::Image`](crate::graphics::Image) from an existing OpenGL texture.

Methods can be chained on it in order to configure it.

 * `origin`: Change the texture's origin when rendering (default: TopLeft).

Complete the builder by calling [`Self::build()`] to create a [`slint::Image`](crate::graphics::Image):

```
# use i_slint_core::graphics::{BorrowedOpenGLTextureBuilder, Image, IntSize, BorrowedOpenGLTextureOrigin};
# let texture_id = core::num::NonZeroU32::new(1).unwrap();
# let size = IntSize::new(100, 100);
let builder = unsafe { BorrowedOpenGLTextureBuilder::new_gl_2d_rgba_texture(texture_id, size) }
             .origin(BorrowedOpenGLTextureOrigin::TopLeft);

let image: slint::Image = builder.build();
```

Returns true if this brush contains a fully transparent color (alpha value is zero)

```
# use i_slint_core::graphics::*;
assert!(Brush::default().is_transparent());
assert!(Brush::SolidColor(Color::from_argb_u8(0, 255, 128, 140)).is_transparent());
