    0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52,
    0x00, 0x00, 0x00, 0x7B, 0x00, 0x00, 0x01, 0x41,
    0x08, 0x06, 0x00, 0x00, 0x00, 0x9A, 0x38, 0xC4
]);

match reader_size(reader) {
    Ok(dim) => {
        assert_eq!(dim.width, 123);
        assert_eq!(dim.height, 321);
    }
