Return all minimum elements of an iterator.

# Examples

```
use itertools::Itertools;

let a: [i32; 0] = [];
assert_eq!(a.iter().min_set(), Vec::<&i32>::new());

let a = [1];
assert_eq!(a.iter().min_set(), vec![&1]);

let a = [1, 2, 3, 4, 5];
assert_eq!(a.iter().min_set(), vec![&1]);

let a = [1, 1, 1, 1];
assert_eq!(a.iter().min_set(), vec![&1, &1, &1, &1]);
