Provides in-place mutable access to an occupied entry before any
potential inserts into the map.

# Examples

```
# use serde_json::json;
#
let mut map = serde_json::Map::new();
map.entry("serde")
    .and_modify(|e| *e = json!("rust"))
    .or_insert(json!("cpp"));

assert_eq!(map["serde"], "cpp");

map.entry("serde")
    .and_modify(|e| *e = json!("rust"))
    .or_insert(json!("cpp"));

assert_eq!(map["serde"], "rust");
