    PathSegment::MoveTo { abs: true, x: 10.0, y: -20.0 },
    PathSegment::LineTo { abs: false, x: 30.1, y: 0.5 },
    PathSegment::LineTo { abs: false, x: 0.1, y: -20.0 },
