    SignedDuration::new(0, 0),
);
assert_eq!(
    SignedDuration::saturating_seconds_f32(f32::NEG_INFINITY),
    SignedDuration::MIN,
);
assert_eq!(
    SignedDuration::saturating_seconds_f32(f32::INFINITY),
    SignedDuration::MAX,
);
```

