This can even be used in a generic `const N: usize` context, provided the
genericity is guarded by a `where` clause:

```rust
use typenum::*;

struct MyStruct<const N: usize>;

trait MyTrait { type AssocType; }

impl<const N: usize> MyTrait
    for MyStruct<N>
where
    Const<N> : ToUInt,
{
