# fn run() -> Result<(), Box<dyn Error>> {
let mut url = Url::parse("https://example.org/")?;

url.set_port(Some(443)).map_err(|_| "cannot be base")?;
assert!(url.port().is_none());
# Ok(())
# }
# run().unwrap();
```

