Create a new empty `ArrayVec`.

The maximum capacity is given by the generic parameter `CAP`.

```
use arrayvec::ArrayVec;

let mut array = ArrayVec::<_, 16>::new();
array.push(1);
array.push(2);
assert_eq!(&array[..], &[1, 2]);
assert_eq!(array.capacity(), 16);
