        .arg(
            Arg::new("bar").short('b').action(ArgAction::SetTrue)
        )
}

#[test]
fn verify_app() {
    cmd().debug_assert();
}

let m = cmd().get_matches_from(vec!["foo", "-b"]);
println!("{}", m.get_flag("bar"));
```

