Setting `Arg::requires_ifs(["val", "arg"])` requires that the `arg` be used at runtime if the
defining argument's value is equal to `val`. If the defining argument's value is anything other
than `val`, `arg` isn't required.

```rust
# use clap_builder as clap;
# use clap::{Command, Arg, error::ErrorKind, ArgAction};
let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .requires_ifs([
            ("special.conf", "opt"),
            ("other.conf", "other"),
        ])
        .long("config"))
    .arg(Arg::new("opt")
        .long("option")
        .action(ArgAction::Set))
    .arg(Arg::new("other"))
    .try_get_matches_from(vec![
        "prog", "--config", "special.conf"
    ]);

assert!(res.is_err()); // We  used --config=special.conf so --option <val> is required
assert_eq!(res.unwrap_err().kind(), ErrorKind::MissingRequiredArgument);
```

Setting `Arg::requires_ifs` with [`ArgPredicate::IsPresent`] and *not* supplying all the
arguments is an error.

```rust
# use clap_builder as clap;
# use clap::{Command, Arg, error::ErrorKind, ArgAction, builder::ArgPredicate};
let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .requires_ifs([
            (ArgPredicate::IsPresent, "input"),
            (ArgPredicate::IsPresent, "output"),
        ])
        .long("config"))
    .arg(Arg::new("input"))
    .arg(Arg::new("output"))
    .try_get_matches_from(vec![
        "prog", "--config", "file.conf", "in.txt"
    ]);

assert!(res.is_err());
