issues.

## Examples

```
use dactyl::traits::SaturatingFrom;

assert_eq!(
    u64::saturating_from(f64::NEG_INFINITY),
    0, // Saturated.
);
assert_eq!(
    u64::saturating_from(f64::INFINITY),
    18446744073709551615, // Saturated.
);
```

# (ASCII) Bytes to Signed.

Parse a `i64` from an ASCII byte slice.

## Examples

```
use dactyl::traits::BytesToSigned;

assert_eq!(
    i64::btoi(b"-9223372036854775808"),
    Some(i64::MIN),
);
assert_eq!(
    i64::btoi(b"9223372036854775807"),
    Some(i64::MAX),
);

// Leading zeroes are fine.
assert_eq!(
    i64::btoi(b"00000123"),
    Some(123),
);

// These are all bad.
assert!(i64::btoi(&[]).is_none()); // Empty.
assert!(i64::btoi(b" 2223231  ").is_none()); // Whitespace.
assert!(i64::btoi(b"nope").is_none()); // Not a number.
assert!(i64::btoi(
    b"4402823669209384634633746074317682114550").is_none()
); // Too big.
```

