```
use futures_lite::stream::{self, StreamExt};

# spin_on::spin_on(async {
let l = stream::iter(vec![1, 2, 3]);
let r = stream::iter(vec![4, 5, 6, 7]);
let mut s = l.zip(r);

assert_eq!(s.next().await, Some((1, 4)));
