Calls a fallible closure on each item of the stream, stopping on first error.

# Examples

```
use futures_lite::stream::{self, StreamExt};

# spin_on::spin_on(async {
let mut s = stream::iter(vec![0, 1, 2, 3]);

let mut v = vec![];
let res = s
    .try_for_each(|n| {
        if n < 2 {
            v.push(n);
            Ok(())
        } else {
