    .and_modify(|(_, v)| *v += 1)
    .or_insert(("poneyland", 42));
assert_eq!(
    table.find(hasher(&"poneyland"), |&(k, _)| k == "poneyland"),
    Some(&("poneyland", 43))
);
# }
