```
# use itertools::{EitherOrBoth, EitherOrBoth::{Left, Both}};
// Overwriting a pre-existing value.
let mut either: EitherOrBoth<_, ()> = Left(0_u32);
assert_eq!(*either.insert_left(69), 69);

