# use std::sync::LazyLock;
# use image::GenericImageView;
#
static ICON: LazyLock<ksni::Icon> = LazyLock::new(|| {
    let img = image::load_from_memory_with_format(
        include_bytes!("../examples/custom_icon.png"),
        image::ImageFormat::Png,
    )
    .expect("valid image");
