assert_eq!(until_eof("hello, world"), Err(Err::Incomplete(Needed::Unknown)));
assert_eq!(until_eof("hello, worldeo"), Err(Err::Incomplete(Needed::Unknown)));
assert_eq!(until_eof("1eof2eof"), Ok(("eof2eof", "1")));
```

