assert_eq!(le_f64(&[0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x29, 0x40][..]), Ok((&b""[..], 12.5)));
assert_eq!(le_f64(&b"abc"[..]), Err(Err::Incomplete(Needed::new(5))));
