Saving an etag when caching a file:

```
use reqwest::blocking::Client;
use reqwest::header::ETAG;

# fn run() -> Result<(), Box<dyn std::error::Error>> {
let client = Client::new();

let mut resp = client.get("http://httpbin.org/cache").send()?;
