Parse the body of a block as zero or more statements, possibly
including one trailing expression.

# Example

```
use syn::{braced, token, Attribute, Block, Ident, Result, Stmt, Token};
use syn::parse::{Parse, ParseStream};

// Parse a function with no generics or parameter list.
//
//     fn playground {
//         let mut x = 1;
//         x += 1;
//         println!("{}", x);
//     }
struct MiniFunction {
    attrs: Vec<Attribute>,
    fn_token: Token![fn],
    name: Ident,
    brace_token: token::Brace,
    stmts: Vec<Stmt>,
}

impl Parse for MiniFunction {
    fn parse(input: ParseStream) -> Result<Self> {
        let outer_attrs = input.call(Attribute::parse_outer)?;
        let fn_token: Token![fn] = input.parse()?;
        let name: Ident = input.parse()?;

        let content;
        let brace_token = braced!(content in input);
        let inner_attrs = content.call(Attribute::parse_inner)?;
        let stmts = content.call(Block::parse_within)?;

        Ok(MiniFunction {
            attrs: {
                let mut attrs = outer_attrs;
                attrs.extend(inner_attrs);
                attrs
            },
            fn_token,
            name,
            brace_token,
            stmts,
        })
    }
}
```

Creates an error spanning the given cursor range.

# Example

This parses a sequence of '+'-separated lifetimes and types like
`Vec<u8> + dyn Display + 'static`, at least one of which must be a type.

```
use syn::{Lifetime, Token, Type};
use syn::parse::{Error, ParseStream, Result};

enum Thing {
    Lifetime(Lifetime),
    Type(Type),
}

fn parse_things(input: ParseStream) -> Result<Vec<Thing>> {
    let things_begin = input.cursor();
    let things_end;
    let mut things = Vec::new();
    let mut has_type = false;
    loop {
        if input.peek(Lifetime) {
            let lifetime: Lifetime = input.parse()?;
            things.push(Thing::Lifetime(lifetime));
        } else {
            let ty = input.call(Type::without_plus)?;
            things.push(Thing::Type(ty));
            has_type = true;
        }
        let plus_token: Option<Token![+]> = input.parse()?;
        if plus_token.is_none() {
            things_end = input.cursor();
            break;
        }
    }

    if has_type {
        Ok(things)
    } else {
        let msg = "things must not be all lifetimes, at least one type is required";
        Err(Error::new_range(things_begin..things_end, msg))
    }
}
```

```text
error: things must not be all lifetimes, at least one type is required
 --> example.rs:4:23
  |
4 |     example!(THINGS = 'a + 'b, ...);
  |                       ^^^^^^^
```

Constructs a helper for peeking at the next token in this stream and
building an error message if it is not one of a set of expected tokens.

# Example

```
use syn::{ConstParam, Ident, Lifetime, LifetimeParam, Result, Token, TypeParam};
use syn::parse::{Parse, ParseStream};

// A generic parameter, a single one of the comma-separated elements inside
// angle brackets in:
//
//     fn f<T: Clone, 'a, 'b: 'a, const N: usize>() { ... }
//
// On invalid input, lookahead gives us a reasonable error message.
//
//     error: expected one of: identifier, lifetime, `const`
//       |
//     5 |     fn f<!Sized>() {}
//       |          ^
enum GenericParam {
    Type(TypeParam),
    Lifetime(LifetimeParam),
    Const(ConstParam),
}

impl Parse for GenericParam {
    fn parse(input: ParseStream) -> Result<Self> {
        let lookahead = input.lookahead1();
        if lookahead.peek(Ident) {
            input.parse().map(GenericParam::Type)
        } else if lookahead.peek(Lifetime) {
            input.parse().map(GenericParam::Lifetime)
        } else if lookahead.peek(Token![const]) {
            input.parse().map(GenericParam::Const)
        } else {
            Err(lookahead.error())
        }
    }
}
```

Parses zero or more occurrences of `T` separated by punctuation of type
`P`, with optional trailing punctuation.

Parsing continues until the end of this parse stream. The entire content
of this parse stream must consist of `T` and `P`.

# Example

```
# use quote::quote;
#
use syn::{parenthesized, token, Ident, Result, Token, Type};
use syn::parse::{Parse, ParseStream};
use syn::punctuated::Punctuated;

// Parse a simplified tuple struct syntax like:
//
//     struct S(A, B);
struct TupleStruct {
    struct_token: Token![struct],
    ident: Ident,
    paren_token: token::Paren,
    fields: Punctuated<Type, Token![,]>,
    semi_token: Token![;],
}

impl Parse for TupleStruct {
    fn parse(input: ParseStream) -> Result<Self> {
        let content;
        Ok(TupleStruct {
            struct_token: input.parse()?,
            ident: input.parse()?,
            paren_token: parenthesized!(content in input),
            fields: content.parse_terminated(Type::parse, Token![,])?,
            semi_token: input.parse()?,
        })
    }
}
#
# let input = quote! {
#     struct S(A, B);
# };
# syn::parse2::<TupleStruct>(input).unwrap();
```

