Trait for the policy on handling redirection responses.

# Example

Detecting a cyclic redirection:

```
use http::{Method, Request, Uri};
use std::collections::HashSet;
use tower_http::follow_redirect::policy::{Action, Attempt, Policy};

#[derive(Clone)]
pub struct DetectCycle {
    uris: HashSet<(Method, Uri)>,
}

impl<B, E> Policy<B, E> for DetectCycle {
    fn redirect(&mut self, attempt: &Attempt<'_>) -> Result<Action, E> {
        if self.uris.contains(&(attempt.method().clone(), attempt.location().clone())) {
            Ok(Action::Stop)
        } else {
            self.uris.insert((attempt.previous_method().clone(), attempt.previous().clone()));
            Ok(Action::Follow)
        }
    }
}
```

Middleware for following redirections.

# Overview

The [`FollowRedirect`] middleware retries requests with the inner [`Service`] to follow HTTP
redirections.

The middleware tries to clone the original [`Request`] when making a redirected request.
However, since [`Extensions`][http::Extensions] are `!Clone`, any extensions set by outer
middleware will be discarded. Also, the request body cannot always be cloned. When the
original body is known to be empty by [`Body::size_hint`], the middleware uses `Default`
implementation of the body type to create a new request body. If you know that the body can be
cloned in some way, you can tell the middleware to clone it by configuring a [`policy`].

# Examples

## Basic usage

```
use http::{Request, Response};
use bytes::Bytes;
use http_body_util::Full;
use tower::{Service, ServiceBuilder, ServiceExt};
use tower_http::follow_redirect::{FollowRedirectLayer, RequestUri};

# #[tokio::main]
# async fn main() -> Result<(), std::convert::Infallible> {
# let http_client = tower::service_fn(|req: Request<_>| async move {
#     let dest = "https://www.rust-lang.org/";
#     let mut res = http::Response::builder();
#     if req.uri() != dest {
#         res = res
#             .status(http::StatusCode::MOVED_PERMANENTLY)
#             .header(http::header::LOCATION, dest);
#     }
#     Ok::<_, std::convert::Infallible>(res.body(Full::<Bytes>::default()).unwrap())
# });
let mut client = ServiceBuilder::new()
    .layer(FollowRedirectLayer::new())
    .service(http_client);

let request = Request::builder()
    .uri("https://rust-lang.org/")
    .body(Full::<Bytes>::default())
    .unwrap();

let response = client.ready().await?.call(request).await?;
// Get the final request URI.
assert_eq!(response.extensions().get::<RequestUri>().unwrap().0, "https://www.rust-lang.org/");
# Ok(())
# }
```

## Customizing the `Policy`

You can use a [`Policy`] value to customize how the middleware handles redirections.

```
use http::{Request, Response};
use http_body_util::Full;
use bytes::Bytes;
use tower::{Service, ServiceBuilder, ServiceExt};
use tower_http::follow_redirect::{
    policy::{self, PolicyExt},
    FollowRedirectLayer,
};

#[derive(Debug)]
enum MyError {
    TooManyRedirects,
    Other(tower::BoxError),
}

# #[tokio::main]
# async fn main() -> Result<(), MyError> {
# let http_client =
#     tower::service_fn(|_: Request<Full<Bytes>>| async { Ok(Response::new(Full::<Bytes>::default())) });
let policy = policy::Limited::new(10) // Set the maximum number of redirections to 10.
    // Return an error when the limit was reached.
    .or::<_, (), _>(policy::redirect_fn(|_| Err(MyError::TooManyRedirects)))
    // Do not follow cross-origin redirections, and return the redirection responses as-is.
    .and::<_, (), _>(policy::SameOrigin::new());

let mut client = ServiceBuilder::new()
    .layer(FollowRedirectLayer::with_policy(policy))
    .map_err(MyError::Other)
    .service(http_client);

// ...
# let _ = client.ready().await?.call(Request::default()).await?;
# Ok(())
# }
```

Create a new `Policy` that returns [`Action::Follow`] if either `self` or `other` returns
`Action::Follow`.

[`clone_body`][Policy::clone_body] method of the returned `Policy` tries to clone the body
with both policies.

# Example

```
use tower_http::follow_redirect::policy::{self, Action, Limited, PolicyExt};

#[derive(Clone)]
enum MyError {
    TooManyRedirects,
    // ...
}

let policy = Limited::default().or::<_, (), _>(Err(MyError::TooManyRedirects));
```

Create a new `Policy` that returns [`Action::Follow`] only if `self` and `other` return
`Action::Follow`.

[`clone_body`][Policy::clone_body] method of the returned `Policy` tries to clone the body
with both policies.

# Example

```
use bytes::Bytes;
use http_body_util::Full;
use tower_http::follow_redirect::policy::{self, clone_body_fn, Limited, PolicyExt};

enum MyBody {
    Bytes(Bytes),
    Full(Full<Bytes>),
}

let policy = Limited::default().and::<_, _, ()>(clone_body_fn(|body| {
    if let MyBody::Bytes(buf) = body {
        Some(MyBody::Bytes(buf.clone()))
    } else {
        None
    }
}));
```

A [`MakeClassifier`] that produces new classifiers by cloning an inner classifier.

When a type implementing [`ClassifyResponse`] doesn't depend on information
from the request, [`SharedClassifier`] can be used to turn an instance of that type
into a [`MakeClassifier`].

# Example

```
use std::fmt;
use tower_http::classify::{
    ClassifyResponse, ClassifiedResponse, NeverClassifyEos,
    SharedClassifier, MakeClassifier,
};
use http::Response;

// A response classifier that only considers errors to be failures.
#[derive(Clone, Copy)]
struct MyClassifier;

impl ClassifyResponse for MyClassifier {
    type FailureClass = String;
    type ClassifyEos = NeverClassifyEos<Self::FailureClass>;

    fn classify_response<B>(
        self,
        _res: &Response<B>,
    ) -> ClassifiedResponse<Self::FailureClass, Self::ClassifyEos> {
        ClassifiedResponse::Ready(Ok(()))
    }

    fn classify_error<E>(self, error: &E) -> Self::FailureClass
    where
        E: fmt::Display + 'static,
    {
        error.to_string()
    }
}

// Some function that requires a `MakeClassifier`
fn use_make_classifier<M: MakeClassifier>(make: M) {
    // ...
}

// `MyClassifier` doesn't implement `MakeClassifier` but since it doesn't
// care about the incoming request we can make `MyClassifier`s by cloning.
// That is what `SharedClassifier` does.
let make_classifier = SharedClassifier::new(MyClassifier);

// We now have a `MakeClassifier`!
use_make_classifier(make_classifier);
```

Decorates a [`Service`], transforming either the request or the response.

Often, many of the pieces needed for writing network applications can be
reused across multiple services. The `Layer` trait can be used to write
reusable components that can be applied to very different kinds of services;
for example, it can be applied to services operating on different protocols,
and to both the client and server side of a network transaction.

# Log

Take request logging as an example:

```rust
# use tower_service::Service;
# use std::task::{Poll, Context};
# use tower_layer::Layer;
# use std::fmt;

pub struct LogLayer {
    target: &'static str,
}

impl<S> Layer<S> for LogLayer {
    type Service = LogService<S>;

    fn layer(&self, service: S) -> Self::Service {
        LogService {
            target: self.target,
            service
        }
    }
}

// This service implements the Log behavior
pub struct LogService<S> {
    target: &'static str,
    service: S,
}

impl<S, Request> Service<Request> for LogService<S>
where
    S: Service<Request>,
    Request: fmt::Debug,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&mut self, request: Request) -> Self::Future {
        // Insert log statement here or other functionality
        println!("request = {:?}, target = {:?}", request, self.target);
        self.service.call(request)
    }
}
```

The above log implementation is decoupled from the underlying protocol and
is also decoupled from client or server concerns. In other words, the same
log middleware could be used in either a client or a server.

[`Service`]: https://docs.rs/tower/*/tower/trait.Service.html

Returns a new [`LayerFn`] that implements [`Layer`] by calling the
given function.

The [`Layer::layer`] method takes a type implementing [`Service`] and
returns a different type implementing [`Service`]. In many cases, this can
be implemented by a function or a closure. The [`LayerFn`] helper allows
writing simple [`Layer`] implementations without needing the boilerplate of
a new struct implementing [`Layer`].

# Example
```rust
# use tower::Service;
# use std::task::{Poll, Context};
# use tower_layer::{Layer, layer_fn};
# use std::fmt;
# use std::convert::Infallible;
#
// A middleware that logs requests before forwarding them to another service
pub struct LogService<S> {
    target: &'static str,
    service: S,
}

impl<S, Request> Service<Request> for LogService<S>
where
    S: Service<Request>,
    Request: fmt::Debug,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&mut self, request: Request) -> Self::Future {
        // Log the request
        println!("request = {:?}, target = {:?}", request, self.target);

        self.service.call(request)
    }
}

// A `Layer` that wraps services in `LogService`
let log_layer = layer_fn(|service| {
    LogService {
        service,
        target: "tower-docs",
    }
});

// An example service. This one uppercases strings
let uppercase_service = tower::service_fn(|request: String| async move {
    Ok::<_, Infallible>(request.to_uppercase())
});

// Wrap our service in a `LogService` so requests are logged.
let wrapped_service = log_layer.layer(uppercase_service);
```

[`Service`]: https://docs.rs/tower-service/latest/tower_service/trait.Service.html
[`Layer::layer`]: crate::Layer::layer

An asynchronous function from a `Request` to a `Response`.

The `Service` trait is a simplified interface making it easy to write
network applications in a modular and reusable way, decoupled from the
underlying protocol. It is one of Tower's fundamental abstractions.

# Functional

A `Service` is a function of a `Request`. It immediately returns a
`Future` representing the eventual completion of processing the
request. The actual request processing may happen at any time in the
future, on any thread or executor. The processing may depend on calling
other services. At some point in the future, the processing will complete,
and the `Future` will resolve to a response or error.

At a high level, the `Service::call` function represents an RPC request. The
`Service` value can be a server or a client.

# Server

An RPC server *implements* the `Service` trait. Requests received by the
server over the network are deserialized and then passed as an argument to the
server value. The returned response is sent back over the network.

As an example, here is how an HTTP request is processed by a server:

```rust
# use std::pin::Pin;
# use std::task::{Poll, Context};
# use std::future::Future;
# use tower_service::Service;
use http::{Request, Response, StatusCode};

struct HelloWorld;

impl Service<Request<Vec<u8>>> for HelloWorld {
    type Response = Response<Vec<u8>>;
    type Error = http::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    fn call(&mut self, req: Request<Vec<u8>>) -> Self::Future {
        // create the body
        let body: Vec<u8> = "hello, world!\n"
            .as_bytes()
            .to_owned();
        // Create the HTTP response
        let resp = Response::builder()
            .status(StatusCode::OK)
            .body(body)
            .expect("Unable to create `http::Response`");

        // create a response in a future.
        let fut = async {
            Ok(resp)
        };

        // Return the response as an immediate future
        Box::pin(fut)
    }
}
```

# Client

A client consumes a service by using a `Service` value. The client may
issue requests by invoking `call` and passing the request as an argument.
It then receives the response by waiting for the returned future.

As an example, here is how a Redis request would be issued:

```rust,ignore
let client = redis::Client::new()
    .connect("127.0.0.1:6379".parse().unwrap())
    .unwrap();

let resp = client.call(Cmd::set("foo", "this is the value of foo")).await?;

// Wait for the future to resolve
println!("Redis response: {:?}", resp);
```

# Middleware / Layer

More often than not, all the pieces needed for writing robust, scalable
network applications are the same no matter the underlying protocol. By
unifying the API for both clients and servers in a protocol agnostic way,
it is possible to write middleware that provide these pieces in a
reusable way.

Take timeouts as an example:

```rust
use tower_service::Service;
use tower_layer::Layer;
use futures::FutureExt;
use std::future::Future;
use std::task::{Context, Poll};
use std::time::Duration;
use std::pin::Pin;
use std::fmt;
use std::error::Error;

// Our timeout service, which wraps another service and
// adds a timeout to its response future.
pub struct Timeout<T> {
    inner: T,
    timeout: Duration,
}

impl<T> Timeout<T> {
    pub const fn new(inner: T, timeout: Duration) -> Timeout<T> {
        Timeout {
            inner,
            timeout
        }
    }
}

// The error returned if processing a request timed out
#[derive(Debug)]
pub struct Expired;

impl fmt::Display for Expired {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "expired")
    }
}

impl Error for Expired {}

// We can implement `Service` for `Timeout<T>` if `T` is a `Service`
impl<T, Request> Service<Request> for Timeout<T>
where
    T: Service<Request>,
    T::Future: 'static,
    T::Error: Into<Box<dyn Error + Send + Sync>> + 'static,
    T::Response: 'static,
{
    // `Timeout` doesn't modify the response type, so we use `T`'s response type
    type Response = T::Response;
    // Errors may be either `Expired` if the timeout expired, or the inner service's
    // `Error` type. Therefore, we return a boxed `dyn Error + Send + Sync` trait object to erase
    // the error's type.
    type Error = Box<dyn Error + Send + Sync>;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        // Our timeout service is ready if the inner service is ready.
        // This is how backpressure can be propagated through a tree of nested services.
       self.inner.poll_ready(cx).map_err(Into::into)
    }

    fn call(&mut self, req: Request) -> Self::Future {
        // Create a future that completes after `self.timeout`
        let timeout = tokio::time::sleep(self.timeout);

        // Call the inner service and get a future that resolves to the response
        let fut = self.inner.call(req);

        // Wrap those two futures in another future that completes when either one completes
        //
        // If the inner service is too slow the `sleep` future will complete first
        // And an error will be returned and `fut` will be dropped and not polled again
        //
        // We have to box the errors so the types match
        let f = async move {
            tokio::select! {
                res = fut => {
                    res.map_err(|err| err.into())
                },
                _ = timeout => {
                    Err(Box::new(Expired) as Box<dyn Error + Send + Sync>)
                },
            }
        };

        Box::pin(f)
    }
}

// A layer for wrapping services in `Timeout`
pub struct TimeoutLayer(Duration);

impl TimeoutLayer {
    pub const fn new(delay: Duration) -> Self {
        TimeoutLayer(delay)
    }
}

impl<S> Layer<S> for TimeoutLayer {
    type Service = Timeout<S>;

    fn layer(&self, service: S) -> Timeout<S> {
        Timeout::new(service, self.0)
    }
}
```

The above timeout implementation is decoupled from the underlying protocol
and is also decoupled from client or server concerns. In other words, the
same timeout middleware could be used in either a client or a server.

# Backpressure

Calling a `Service` which is at capacity (i.e., it is temporarily unable to process a
request) should result in an error. The caller is responsible for ensuring
that the service is ready to receive the request before calling it.

`Service` provides a mechanism by which the caller is able to coordinate
readiness. `Service::poll_ready` returns `Ready` if the service expects that
it is able to process a request.

# Be careful when cloning inner services

Services are permitted to panic if `call` is invoked without obtaining `Poll::Ready(Ok(()))`
from `poll_ready`. You should therefore be careful when cloning services for example to move
them into boxed futures. Even though the original service is ready, the clone might not be.

Therefore this kind of code is wrong and might panic:

```rust
# use std::pin::Pin;
# use std::task::{Poll, Context};
# use std::future::Future;
# use tower_service::Service;
#
struct Wrapper<S> {
    inner: S,
}

impl<R, S> Service<R> for Wrapper<S>
where
    S: Service<R> + Clone + 'static,
    R: 'static,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: R) -> Self::Future {
        let mut inner = self.inner.clone();
        Box::pin(async move {
            // `inner` might not be ready since its a clone
            inner.call(req).await
        })
    }
}
```

You should instead use [`std::mem::replace`] to take the service that was ready:

```rust
# use std::pin::Pin;
# use std::task::{Poll, Context};
# use std::future::Future;
# use tower_service::Service;
#
struct Wrapper<S> {
    inner: S,
}

impl<R, S> Service<R> for Wrapper<S>
where
    S: Service<R> + Clone + 'static,
    R: 'static,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: R) -> Self::Future {
        let clone = self.inner.clone();
        // take the service that was ready
        let mut inner = std::mem::replace(&mut self.inner, clone);
        Box::pin(async move {
            inner.call(req).await
        })
    }
}
```

