Turn this `SendBody` into a reader.

This is useful in [`Middleware`][crate::middleware::Middleware] to make changes to the
body before sending it.

```
use ureq::{SendBody, Body};
use ureq::middleware::MiddlewareNext;
use ureq::http::{Request, Response, header::HeaderValue};
use std::io::Read;

fn my_middleware(req: Request<SendBody>, next: MiddlewareNext)
    -> Result<Response<Body>, ureq::Error> {

    // Take apart the request.
    let (parts, body) = req.into_parts();

    // Take the first 100 bytes of the incoming send body.
    let mut reader = body.into_reader().take(100);

    // Create a new SendBody.
    let new_body = SendBody::from_reader(&mut reader);

    // Reconstitute the request.
    let req = Request::from_parts(parts, new_body);

    // set my bespoke header and continue the chain
    next.handle(req)
}
```

Allows configuring this request behaviour, using a specific [`Agent`].

This method allows configuring the request by using a user-provided `Agent` and performing
additional configurations on top.
This method returns a `WithAgent` struct that it is possible to call `configure()` and `run()`
on to configure the request behaviour, or run the request.

# Example

```
use ureq::{http, Agent, RequestExt, Error};
use std::time::Duration;
let agent = Agent::config_builder()
    .timeout_global(Some(Duration::from_secs(30)))
    .build()
    .new_agent();

let request: Result<http::Response<_>, Error> = http::Request::builder()
            .method(http::Method::GET)
            .uri("http://foo.bar")
            .body(())
            .unwrap()
            .with_agent(&agent)
            .run();
```
# Example with further customizations

In this example we use a specific agent, but apply a request-specific configuration on top.

```
use ureq::{http, Agent, RequestExt, Error};
use std::time::Duration;
let mut agent = Agent::config_builder()
    .timeout_global(Some(Duration::from_secs(30)))
    .build()
    .new_agent();

let request: Result<http::Response<_>, Error> = http::Request::builder()
            .method(http::Method::GET)
            .uri("http://foo.bar")
            .body(())
            .unwrap()
            .with_agent(&agent)
            .configure()
            .http_status_as_error(false)
            .run();
```

