# use winnow::error::Needed::Size;
use winnow::ascii::float;

fn parser<'s>(s: &mut &'s str) -> ModalResult<f64> {
  float(s)
}

assert_eq!(parser.parse_peek("11e-1"), Ok(("", 1.1)));
assert_eq!(parser.parse_peek("123E-02"), Ok(("", 1.23)));
