assert_eq!(parser.parse_peek("21c"), Ok(("c", "21")));
assert_eq!(parser.parse_peek("21"), Ok(("", "21")));
assert_eq!(parser.parse_peek("a21c"), Ok(("a21c", "")));
assert_eq!(parser.parse_peek(""), Ok(("", "")));
