use zerovec::VarZeroVec;

let vzv = VarZeroVec::<str>::from(&["a", "b", "c", "d"]);
# let mut pairs: Vec<(&str, &str)> = Vec::new();

let mut it = vzv.iter().peekable();
while let (Some(x), Some(y)) = (it.next(), it.peek()) {
    // Evaluate (x, y) here.
#   pairs.push((x, y));
}
# assert_eq!(pairs, &[("a", "b"), ("b", "c"), ("c", "d")]);
```

